// One timing/selection source for browser and Android. Never edits the generated character PNGs.
const fs=require('node:fs'),path=require('node:path');
const data=require('../web/sunset-motion-data.js');
const root=path.resolve(__dirname,'..');
const target=path.join(root,'feature/assist/src/main/kotlin/dev/fuelpilot/ui/SunsetMotion.kt');
const longs=values=>'listOf('+values.map(n=>n+'L').join(',')+')';
function render(){return `package dev.fuelpilot.ui

// Generated by tools/generate-sunset-motion.cjs from web/sunset-motion-data.js.
// Newly drawn sunset sheets; historical PodongClips is retained separately.
internal data class SunsetClip(val sheet:String,val columns:Int,val rows:Int,val frames:List<Int>,val durationsMs:List<Long>) {
    val durationMs:Long get()=durationsMs.sum()
}
internal data class SunsetFrame(val index:Int,val nextIndex:Int,val blend:Float)
internal object SunsetMotion {
    val clips=mapOf(
${Object.entries(data.clips).map(([name,c])=>{const sheet=data.sheets[c.sheet];return '        "'+name+'" to SunsetClip("'+c.sheet+'",'+sheet.columns+','+sheet.rows+',listOf('+c.frames.join(',')+'),'+longs(c.durationsMs)+'),';}).join('\n')}
    )
    fun transition(name:String,elapsedMs:Long):SunsetFrame {
        val clip=clips.getValue(name)
        val elapsed=elapsedMs.coerceAtLeast(0).let{if(name=="calm")it%clip.durationMs else it}
        var boundary=0L
        clip.durationsMs.forEachIndexed { i,d ->
            val start=boundary
            boundary+=d
            if(elapsed<boundary) {
                val window=minOf(45L,(d*45L/100L).coerceAtLeast(1L))
                val raw=((elapsed-start-(d-window)).toFloat()/window.toFloat()).coerceIn(0f,1f)
                val eased=raw*raw*(3f-2f*raw)
                val next=(i+1).coerceAtMost(clip.frames.lastIndex)
                return SunsetFrame(i,next,if(next==i)0f else eased)
            }
        }
        return SunsetFrame(clip.frames.lastIndex,clip.frames.lastIndex,0f)
    }
    fun frame(name:String,elapsedMs:Long):Int = transition(name,elapsedMs).index
    fun nextDelay(name:String,elapsedMs:Long,finishAtMs:Long):Long {
        val clip=clips.getValue(name)
        val elapsed=elapsedMs.coerceAtLeast(0).let{if(name=="calm")it%clip.durationMs else it}
        val next=clip.durationsMs.take(frame(name,elapsed)+1).sum()
        return (if(name!="calm" && elapsed>=clip.durationMs)finishAtMs-elapsed else next-elapsed).coerceAtLeast(16)
    }
}
`;}
function verify(){if(fs.readFileSync(target,'utf8').replace(/\r\n/g,'\n')!==render())throw Error('Sunset motion metadata drift. Run node tools/generate-sunset-motion.cjs --write');}
module.exports={render,verify};
if(require.main===module){if(process.argv.includes('--write'))fs.writeFileSync(target,render());else verify();}
